preConditionHook:
// CONSOLIDATION BREAKOUT BAR (Brian's notes ON-30-b, #30). This bar OPENS
// inside the range of the prior zoneBars bars and closes at least breakoutAtr
// x ATR(zoneBars) beyond it. The zone and the ATR are both read one bar ago,
// at the zone's last bar, so the breakout bar's own true range does not
// inflate its benchmark. Pair it in pane 2 with RangeWidthBelowAtrMultiple at
// lag 1 (rangeLookback = atrLookback = zoneBars) for the consolidation test.
//
// EL: atrVal = WFSafe_AvgTrueRange(zoneBars); ... atrVal[1]. A read of the
// VARIABLE's history, 0 on the first evaluated bar: mirrored by keeping last
// bar's atr (zero-initialised) before this bar's update.
atrPrev = atr;
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded with a full sum on the study's first calculated bar, thereafter
// S += TrueRange - TrueRange[Length] as TWO statements (EL evaluates
// S[1] + in - out left to right; folding it rounds differently), re-seeding
// when the length changes. Same block as RangeWidthBelowAtrMultiple and
// AtrProfitTarget (the reference).
if (atrLength != (int)zoneBars) {
    atrSum = 0.0;
    for (int i = 0; i < (int)zoneBars; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)zoneBars;
} else {
    const int out = (int)zoneBars;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)zoneBars;
// EL: Highest(...)[1] / Lowest(...)[1] on the zone -- Extremes over
// bars 1 .. zoneBars, seeded at bar 1, strict toleranced comparison.
zh = high[1];
zl = low[1];
for (int i = 1; i < (int)zoneBars; ++i) {
    if (el_gt(high[1 + i], zh)) zh = high[1 + i];
    if (el_lt(low[1 + i], zl)) zl = low[1 + i];
}
